        },
        {
          "day": 2,
          "date": "2026-08-14",
          "risk_level": "medium",
          "risk_tags": [
            "cold"
          ],
          "notes": "白天最高约6°C、最低约1°C；同样需以室内活动为主并避免夜间滨水活动。"
        }
      ],
      "adjustment_required": true,
      "adjustment_notes": "必须提高室内活动比例（>=50%），每次室外活动不超过1.5小时；避免18:00-24:00的滨水夜间活动；灵活调整景点顺序以利用较暖/较有遮蔽的时段（如先安排室外短游再转室内博物馆或商街）。"
    },
    "itinerary": {
      "daily_itinerary": [
        {
          "day": 1,
          "date": "2026-08-13",
          "attraction_poi_ids": [
            "hz001",
            "hz004"
          ],
          "notes": "上午：西湖（hz001）短时观光与拍照，控制连续室外时间在1–1.5小时内，优先选择靠近西湖博物馆等室内点过渡；中午于室内餐厅用餐并保暖。下午/傍晚：前往清河坊历史文化街区（hz004），以室内商铺与餐馆为主的逛吃（约2小时），避免18:00后靠近湖边长时间停留。该日总体保证至少50%室内活动（西湖安排短时户外+临近室内展馆穿插，清河坊以室内为主）。"
